        c.Put{value: amount1}(0);

        vm.prank(bob);
        c.Put{value: amount2}(0);

        // The invariant: the sum of all balances across all holders must equal the contract's Ether balance
        // Since we only have two holders and no collects, total balance = amount1 + amount2
