import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initVal, uint256 collectAmt, uint256 lockTime) public {
        // Restrict domain to avoid reverts in the reference that are not related to the bug
        // 1. initVal must be >= collectAmt so Collect can succeed in reference
        vm.assume(initVal >= collectAmt);
        // 2. initVal must be >= MinSum (which we set) so Collect condition passes
        // 3. avoid overflow in Put for the reference via the required check
        vm.assume(initVal <= type(uint256).max - initVal);
        // 4. lockTime must not cause overflow in timestamp addition
        vm.assume(lockTime <= type(uint256).max - block.timestamp);

        // Setup: initialize contract, set MinSum to 0, and put funds for the test sender
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();

        address sender = address(0x1234);
        vm.deal(sender, initVal);
        vm.prank(sender);
        c.Put{value: initVal}(lockTime);

        // Warp past unlock time so Collect can succeed
        vm.warp(block.timestamp + lockTime + 1);

        // Record balance before Collect
        uint256 balBefore = c.Acc(sender).balance;

        // Perform Collect
        vm.prank(sender);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmt));
        // In the reference C, Collect may succeed or revert due to internal call to LogFile at address(0) failing.
        // We only assert on cases where Collect actually executed (i.e., did not revert).
        // Since the Log is broken anyway, we just need to observe the state change when it doesn't revert.
        // If it reverts, we skip the assertion because the state didn't change.
        if (ok) {
            uint256 balAfter = c.Acc(sender).balance;
            // General rule: balance after Collect cannot increase relative to balance before Collect.
            // The mutant allows an overflowed balance to wrap and become larger after subtraction.
            assertTrue(balAfter <= balBefore);
        }
