pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 _lockTime, uint256 collectAmt) public {
        // Bound to admissible domain: _lockTime can be any uint256, collectAmt any uint256.
        // We don't artificially restrict _lockTime to small values, letting the fuzzer explore overflow territory.
        address sender = address(0x1234);
        uint256 depositAmt = 1 ether;

        // Setup: initialize contract, set minimal sum to 0 so collect is allowed for any positive balance
        c.SetMinSum(0);
        c.Initialized();

        // Fund sender and deposit
        vm.deal(sender, depositAmt);
        vm.prank(sender);
        c.Put{value: depositAmt}(_lockTime);

        // Warp forward by a moderate amount so that reference Put's unlockTime (block.timestamp+_lockTime with overflow guard) is safely in the future.
        // Without overflow, block.timestamp+_lockTime might be enormous if _lockTime is large, but we warp to a point where
        // reference unlockTime has NOT passed yet if overflow prevention is active.
        // We warp to 1 day after deposit (still well before normal unlockTime if _lockTime is large and non-overflowed).
        vm.warp(block.timestamp + 1 days);

        // Try to collect an amount <= balance.
        // Bound collectAmt to not exceed balance, otherwise collect will simply not proceed in either version.
        collectAmt = bound(collectAmt, 1, depositAmt);

        bool refSuccess;
        try c.Collect(collectAmt) {
            refSuccess = true;
        } catch {
            refSuccess = false;
        }

        // The property:
        // In the reference contract, a Collect after a Put with a possibly overflowed _lockTime should always FAIL
        // until the correct unlockTime (block.timestamp+_lockTime) is reached. Because we are still well before
        // the legitimate unlockTime (no overflow protection ensures unlockTime is huge or capped safely),
        // the reference must not allow early collection. The mutant lacks the overflow check, so unlockTime can wrap
        // to a small past value, allowing this early Collect to succeed.
        // Thus the invariant: reference should NOT succeed in collecting early.
        assertTrue(!refSuccess, "Reference allowed early collect despite no overflow protection");
    }
}

