        // Record balance before Collect
        uint256 balanceBefore = c.Acc(user).balance;

        // Attempt Collect of _collectAmount bounded by balance and MinSum
        uint256 col = bound(_collectAmount, 1, balanceBefore);
        vm.assume(col >= _minSum);

        bool ok;
        vm.prank(user);
        try c.Collect(col) { ok = true; } catch { ok = false; }

        // Get balance after
        uint256 balanceAfter = c.Acc(user).balance;

        // General rule: if Collect succeeded, balance must have decreased exactly by col.
        // In reference, overflow guard prevents early Collect (reverts), so ok=false when lockTime overflows.
        // Mutant allows success with unlockTime in past, causing balance decrease, violating rule that
        // success implies balanceBefore - col == balanceAfter only when lock valid.
        // We assert: ok == true => balanceAfter == balanceBefore - col
        assertTrue(!ok || balanceAfter == balanceBefore - col);
    }
}

