pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.SetMinSum(0);
        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        c.Initialized();
    }
    function testFuzz_property(uint256 lockTime, uint256 collectAmount, uint256 initialBalance) public {
        // Bound to reasonable ranges to avoid overflow and infeasible execution
        lockTime = bound(lockTime, 0, type(uint128).max);
        collectAmount = bound(collectAmount, 1, type(uint128).max);
        initialBalance = bound(initialBalance, collectAmount, type(uint128).max);

        address alice = makeAddr("alice");
        vm.deal(alice, initialBalance);

        // Alice puts some ether with a lock time
        vm.prank(alice);
        c.Put{value: initialBalance}(lockTime);

        // Warp to exactly unlockTime
        uint unlock = c.Acc(alice).unlockTime;
        // Ensure unlockTime is in the future
        vm.assume(unlock > 0);
        vm.warp(unlock);

        // Snapshot balance before collect
        uint balBefore = c.Acc(alice).balance;
        uint refUnlockBefore = c.Acc(alice).unlockTime;

        // Try to collect on reference (block.timestamp == unlockTime)
        vm.prank(alice);
        bool ok;
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference behavior: when block.timestamp == unlockTime, Collect MUST revert
        assertTrue(!ok);

        // Balance and unlockTime must be unchanged on reference
        assertEq(c.Acc(alice).balance, balBefore);
        assertEq(c.Acc(alice).unlockTime, refUnlockBefore);
    }
}
